func SatisfactionLTE(v int8) predicate.Ticket {
	return predicate.Ticket(sql.FieldLTE(FieldSatisfaction, v))
}

// SatisfactionIsNil applies the IsNil predicate on the "satisfaction" field.
func SatisfactionIsNil() predicate.Ticket {
	return predicate.Ticket(sql.FieldIsNull(FieldSatisfaction))
}

// SatisfactionNotNil applies the NotNil predicate on the "satisfaction" field.
func SatisfactionNotNil() predicate.Ticket {
	return predicate.Ticket(sql.FieldNotNull(FieldSatisfaction))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Ticket) predicate.Ticket {
	return predicate.Ticket(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Ticket) predicate.Ticket {
	return predicate.Ticket(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Ticket) predicate.Ticket {
	return predicate.Ticket(sql.NotPredicates(p))
}
